/* P108 IW-003 (lane M): the pad's go keys — the kind's picture big on the key (go to the nearest 🥚, go to the 🧺), the
   pin small in its corner, in the motion blocks' blue. */
.bg-key-go { position: relative; color: var(--block-motion); }
.bg-key-go::before { position: absolute; top: 5px; left: 5px; width: 15px !important; height: 15px !important; }
.bg-key-go::after { font-size: 26px; line-height: 1; }
.bg-key-go-egg::after { content: '🥚'; }
.bg-key-go-letter::after { content: '✉️'; }
.bg-key-go-stone::after { content: '🪨'; }
.bg-key-go-food::after { content: '🍖'; }
.bg-key-go-ball::after { content: '⚽'; }
.bg-key-go-rock::after { content: '⛰️'; }
.bg-key-go-can::after { content: '🪣'; }
.bg-key-go-basket::after { content: '🧺'; }
.bg-key-go-bowl::after { content: '🥣'; }
.bg-key-go-store::after { content: '📦'; }
.bg-key-go-door::after { content: '🚪'; }
.bg-key-go-site::after { content: '🟫'; }
.bg-key-go-postbox::after { content: '📮'; }
/* P108 IW-003 (lane M): the job card under the world (IW-000's): a dashed paper card, the labels small capitals, the sum a
   pill that turns leaf-green when the job is done. */
.bg-job { border: 2px dashed var(--line); border-radius: 16px; padding: 12px 14px !important; background-color: var(--paper-2) !important; }
.bg-job-l { font-size: 12px !important; font-weight: 800; letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-2) !important; padding-top: 2px; }
.bg-job-lc { flex: none; }
.bg-job-t { font-size: 15px !important; }
.bg-job-sum { align-self: flex-start; border-radius: 999px; padding: 4px 12px; background-color: var(--card); color: var(--ink) !important; font-size: 14px !important; }
.bg-job-sum-full { background-color: var(--leaf) !important; color: var(--card) !important; }
@media (max-width: 480px) { .bg-job-row { flex-wrap: wrap !important; } .bg-job-lc { width: 100% !important; } }
/* P108 IW-003 (lane M): a full meter on the pages wears the page's leaf — the mockup's green darkened for 4.5:1 under its
   white numbers (S3-R5; the kits paint the mockup green, 3.05:1, measured by the page drive once Mamie’s jobs filled their meters). */
.gd-meter.gd-full, .gd3-meter.gd3-full { background-color: var(--leaf) !important; }
/* P108 IW-006 (lane E): the shells a job earned — small, after the meter and the thanks (research principle 2): under the
   win card's thanks a quiet line; on the island a chip for a moment after a lap pays, at the top between the tap line and
   Find my robots (at its foot it covered an islander's bubble, s4 drive); a phone draws it under the island. */
.bg-win-pay { color: var(--ink-2) !important; }
.bg-isle-pay { position: absolute !important; top: 20px !important; left: 50% !important; transform: translateX(-50%); z-index: 7; background: var(--card); border-radius: 999px; padding: 4px 12px; box-shadow: var(--shadow-soft); pointer-events: none; font-size: 15px !important; white-space: nowrap; }
@media (max-width: 600px) { .bg-isle-pay { position: static !important; transform: none; margin-top: 8px; align-self: flex-start; } }

/* Reduced motion: the mockup's own rule. Every animation and transition stops; the tulip still reads by opacity and pose. */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation: none !important; transition: none !important; }
}

/* P108 IW-008 (lane C): the crew — on the plot card, her robots of the job's kind as pills (ink when here) on a dashed
   paper strip; on My robots, the brain line and the copy chips under a hairline, what a copy said in a soft pill. */
.bg-crew { border-top: 2px dashed var(--line); padding-top: 8px; }
.bg-crew-row, .bg-robot-copy .bg-chip { min-height: 44px; }
.bg-crew-said:empty, .bg-robot-said:empty { display: none !important; }
.bg-crew-said, .bg-robot-said { background-color: var(--paper-2); border-radius: 14px; padding: 8px 12px; }
.bg-robot-copy { border-top: 2px dashed var(--line); padding-top: 8px; }
/* P108 IW-006 (lane H): the shop — its button beside the Island page's head (the balance on it), the sheet over the island
   (the win card's veil), the tabs and the robots / jobs to pick as chips that wrap, the items as a grid of cards (a picture,
   a price on the sun, one line), the purchase card's figures. */
.bg-island-top { justify-content: space-between !important; }
.bg-island-top > :first-child { flex: 1 1 auto; min-width: 0; }
.bg-shop-root { flex: none; }
.bg-shop-open { box-shadow: var(--shadow-soft); white-space: nowrap; }
.bg-shop { position: fixed !important; left: 0 !important; right: 0 !important; top: 0 !important; bottom: 0 !important; width: 100vw !important; height: 100vh !important; z-index: 40 !important; display: flex !important; flex-direction: column !important; align-items: center !important; justify-content: flex-start !important; overflow-y: auto !important; background: color-mix(in srgb, var(--paper) 72%, transparent); backdrop-filter: blur(2px); padding: 16px; box-sizing: border-box; }
.bg-shop-panel { width: 100% !important; max-width: 920px !important; box-sizing: border-box; animation: bg-pop 300ms cubic-bezier(0.34, 1.56, 0.64, 1) both; }
.bg-shop-bal { background-color: var(--sun); border-radius: 999px; padding: 4px 12px; white-space: nowrap; }
.bg-shop-tabs, .bg-shop-chips { display: flex !important; flex-direction: row !important; flex-wrap: wrap !important; gap: 8px; }
.bg-shop-items { display: grid !important; grid-template-columns: repeat(auto-fill, minmax(190px, 1fr)); gap: 12px; }
.bg-shop-item { width: 100% !important; box-sizing: border-box; cursor: pointer; border: 2px solid var(--line); box-shadow: none; }
.bg-shop-item-yours, .bg-shop-item-held { border-color: var(--leaf-3); }
.bg-shop-price { background-color: var(--sun); border-radius: 999px; padding: 3px 10px; white-space: nowrap; }
.bg-shop-tag { align-self: flex-start; background-color: var(--leaf-2); border-radius: 999px; padding: 2px 10px; }
.bg-shop-card { background-color: var(--paper-2) !important; box-shadow: none; }
.bg-shop-fig { display: inline-block; }
.bg-shop-left { background-color: var(--leaf-2); border-radius: 999px; padding: 2px 10px; }
.bg-shop-done { align-self: flex-start; background-color: var(--leaf-2); border-radius: 14px; padding: 6px 12px; }
.bg-shop-short { background-color: var(--tidy); border: 2px solid var(--tidy-edge); border-radius: 14px; padding: 6px 12px; }
@media (max-width: 600px) { .bg-island-top { flex-wrap: wrap !important; } .bg-shop { padding: 8px; } .bg-shop-items { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 8px; } }
/* P108 IW-006 owed (s5, lane O): the win card's "Now in the shop" — quiet, after the thanks and the pay line (principle 2);
   My robots' "Send to a job" chips under a hairline, as the copy chips are. A chip on My robots (a card's, and the hats
   of the stage's options) wraps inside its panel: a job's title, and a hat still to earn ("Chapeau tournesol · un cadeau
   de Mamie Rose", 405 px at 390 FR, measured by this lane's drive — the page scrolled sideways), never wider. */
.bg-win-shop { color: var(--ink-2) !important; }
.bg-robot-send { border-top: 2px dashed var(--line); padding-top: 8px; }
.bg-robot-send .bg-chip { min-height: 44px; }
.bg-robot-card .bg-chip, .bg-robo .bg-chip { max-width: 100%; box-sizing: border-box; }
.bg-robot-card .bg-chip *, .bg-robo .bg-chip * { white-space: normal !important; overflow-wrap: anywhere; max-width: 100%; }
